import { useState } from "react";

export default function BuyActionWindow({ Name2, Price }) {
  let [Quantity, SetQuantity] = useState(1);
  let [Price2, SetPrice] = useState(Price);
  function handleQuantityChange(e) {
    console.log("Calling");

    SetQuantity(e.target.value);
    let newPrise = e.target.value * Price2;
    SetPrice(() => {
      return newPrise;
    });
  }
  function handleBuy() {}

  return (
    <div className="container" style={{ height: "10rem", width: "15rem" }}>
      <form>
        <div className="row">
          <div className="col-6">
            <legend>Qty.</legend>
            <input
              min={1}
              onChange={(e) => {
                handleQuantityChange(e);
              }}
              style={{ height: "2rem", width: "7rem" }}
              type="number"
              name="qty"
              value={Quantity}
            ></input>
          </div>
          <div className="col-6">
            <legend>Price</legend>
            <input
              value={Price2}
              style={{
                height: "2rem",
                width: "7rem",
                marginLeft: "0.5rem",
              }}
              type="number"
              name="price"
            ></input>
          </div>
        </div>
        <div className="row" style={{ marginTop: "30px" }}>
          <div className="col-6">
            <p style={{ fontSize: "0.6rem" }}>
              <b>Margin required $140.65</b>
            </p>
          </div>
          <div className="col-6">
            <button
              onClick={handleBuy}
              style={{
                width: "3rem",
                height: "1.8rem",
                backgroundColor: "skyblue",
                marginleft: "10px",
              }}
            >
              Buy
            </button>
            <button
              style={{
                width: "4.5rem",
                height: "1.8rem",
                marginLeft: "5px",
              }}
            >
              Cancel
            </button>
          </div>
        </div>
      </form>
    </div>
  );
}
